    try:
        ServerSentEvent(id="123\n456", event="update")
        print("Test 2 (ID with \\n): FAILED (Expected ValueError)")
    except ValueError as e:
        if "SSE field must not contain newline characters" in str(e):
            print("Test 2 (ID with \\n): PASSED")
        else:
            print(f"Test 2 (ID with \\n): FAILED (Wrong error: {e})")
    except Exception as e:
        print(f"Test 2 (ID with \\n): FAILED (Unexpected exception: {e})")

    # Test 3: Event with carriage return (\r)
    try:
        ServerSentEvent(id="123", event="update\r")
        print("Test 3 (Event with \\r): FAILED (Expected ValueError)")
    except ValueError as e:
        if "SSE field must not contain newline characters" in str(e):
            print("Test 3 (Event with \\r): PASSED")
        else:
            print(f"Test 3 (Event with \\r): FAILED (Wrong error: {e})")
    except Exception as e:
        print(f"Test 3 (Event with \\r): FAILED (Unexpected exception: {e})")

if __name__ == "__main__":
    test_sse_validation()
